local Monsters = {}

LuaTimer:scheduleTimer(function()
    for _, monster in pairs(Monsters) do
        monster:onUpdate()
    end
end, 100)

function MonsterManager:init()
    for _, monster_config in pairs(MonsterConfig:getAllMonsterConfig()) do
        if type(MonsterMap[tonumber(monster_config.type)]) == "string" then
            local dir = MonsterMap[tonumber(monster_config.type)]
            MonsterMap[tonumber(monster_config.type)] = Plugins.Require("item_skill", dir)
        end
    end

    BaseListener.registerCallBack(CEvents.PlayerReadyEvent, function(player)
        if not isGameStart then
            return
        end
        self:syncMonsters(player)
    end)

end

function MonsterManager:createMonster(position, monster_type, player, ...)
    local config = MonsterConfig:getConfigByType(monster_type)
    if not config then
        return false
    end
    if not player or self:getMonsterNum(monster_type, player) < config.maxNum then
        local monsterClass = MonsterMap[monster_type]
        if monsterClass and type(monsterClass) == "table" then
            local monster = monsterClass.new(position, config, player, ...)
            return true, monster and monster.entityId or 0
        end
    end
    if player then
        player:sendPacket({
            pid = "ShowGameTip",
            lang = "prop.common.tip.num.limit",
            paramsList = {config.maxNum}
        })
    end
    return false
end

function MonsterManager:addMonster(monster)
    Monsters[tostring(monster.entityId)] = monster
end

function MonsterManager:removeMonster(monster)
    Monsters[tostring(monster.entityId)] = nil
end

function MonsterManager:getMonster(entityId)
    return Monsters[tostring(entityId)]
end

function MonsterManager:getMonsterNum(type, player)
    local num = 0
    for _, monster in pairs(Monsters) do
        if type == monster.config.type and monster.creator == player then
            num = num + 1
        end
    end
    return num
end

function MonsterManager:checkInBlock(player, itemId, blockPos)
    for _, monster in pairs(Monsters) do
        monster:checkInBlock(player, itemId, blockPos)
    end
end

function MonsterManager:clearMonster()
    local monsters = {}
    for _, monster in pairs(Monsters) do
        table.insert(monsters, monster)
    end
    for _, monster in pairs(monsters) do
        monster:setDead()
    end
    Monsters = {}
end

function MonsterManager:setMonsterDieById(entityId)
    local monster = self:getMonster(entityId)
    if monster then
        monster:setDead()
    end
end

function MonsterManager:setMonsterParamsById(entityId, params)
    local monster = self:getMonster(entityId)
    if monster and monster.updateParams then
        monster:updateParams(params)
    end
end

function MonsterManager:onExplode(pos, range, damage)
    for _, monster in pairs(Monsters) do
        if monster:canBeExploded() and BtUtil.calculateDistance(monster.entity.position, pos) <= range then
            local hurt = monster:getExplodeDamage(damage)
            monster:subHp(hurt)
        end
    end
end

function MonsterManager:canMonsterBeExploded(entityId)
    local monster = Monsters[tostring(entityId)]
    if not monster then
        return false
    end
    return monster:canBeExploded()
end

function MonsterManager:onAttack(player, value, damageType, hurter)
    for _, monster in pairs(Monsters) do
        if monster.onPlayerAttack then
            monster:onPlayerAttack(player, value, damageType, hurter)
        end
    end
end

function MonsterManager:syncMonsters(player)
    for _, monster in pairs(Monsters) do
        if monster.syncMonsterInfo then
            monster:syncMonsterInfo(player)
        end
    end
end